from pathlib import Path
import subprocess,json,datetime,os
print('AUDIT_UTC',datetime.datetime.now(datetime.timezone.utc).isoformat())
projects=['telegram-robot-leads','iptvpn-bot','pink-iptv','lowcost-europa','fadego','skill-universal','Engenheira-reversa']
for name in projects:
 p=Path('/srv/projects')/name
 print('PROJECT',name,'ROOT_REAL',p.is_dir() and not p.is_symlink())
 if not p.is_dir() or p.is_symlink():raise RuntimeError('Project root not canonical: '+name)
for label,path in [('telegram-data','/srv/projects/telegram-robot-leads/data'),('telegram-private','/srv/projects/telegram-robot-leads/private'),('expired-activator','/srv/projects/telegram-robot-leads/archive/legacy/20261020-activation'),('ferrari-release','/srv/projects/skill-universal/current'),('fadego-release','/srv/projects/fadego/current')]:
 p=Path(path)
 print('COMPONENT',label,'PRESENT',p.is_dir(),'LINK',p.is_symlink())
 if not p.is_dir():raise RuntimeError('Project component missing: '+label)
for path in ['/var/lib/telegram-robot-leads','/root/project-secrets/telegram-robot-leads','/usr/local/sbin/telegram_leads_activate_20261020.py','/etc/systemd/system/telegram-leads-activate-20261020.service','/etc/systemd/system/telegram-leads-activate-20261020.timer']:
 p=Path(path)
 print('FORMER_LOCATION',path,'ABSENT',not p.exists() and not p.is_symlink())
 if p.exists() or p.is_symlink():raise RuntimeError('Legacy loose file still present: '+path)
private=Path('/srv/projects/telegram-robot-leads/private')
sessions=list(private.glob('*.session'))
print('TELEGRAM_SESSIONS',len(sessions))
if len(sessions)!=2 or any(p.is_symlink() or p.stat().st_size<256 or p.stat().st_mode&0o077 for p in sessions):raise RuntimeError('Protected Telegram session metadata fails')
q=subprocess.run(['pm2','jlist'],capture_output=True,text=True,timeout=19)
if q.returncode:raise RuntimeError('PM2 unavailable')
for name in ('telegram-robot-leads','iptvpn_bot'):
 a=[x for x in json.loads(q.stdout) if x.get('name')==name]
 if len(a)!=1 or (a[0].get('pm2_env') or {}).get('status')!='online':raise RuntimeError('PM2 worker not online: '+name)
 e=a[0]['pm2_env']
 print('PM2',name,'PID',a[0].get('pid'),'CWD',e.get('pm_cwd'),'STATE',e.get('TELEGRAM_OPERATION_STATE') if name=='telegram-robot-leads' else '-')
 if name=='telegram-robot-leads' and (e.get('pm_cwd')!='/srv/projects/telegram-robot-leads' or e.get('TELEGRAM_OPERATION_STATE')!='/srv/projects/telegram-robot-leads/data/operation-state.json'):raise RuntimeError('Telegram runtime path stale')
for name in ['fadego-staging','lowcost-europa','pink-iptv-backend','pink-vpn','nginx','postgresql@16-main','pm2-root','ssh']:
 q=subprocess.run(['systemctl','is-active',name+'.service'],capture_output=True,text=True,timeout=9)
 print('SERVICE',name,q.stdout.strip())
 if q.stdout.strip()!='active':raise RuntimeError('Service inactive: '+name)
for name in ('telegram-leads-activate-20261020.timer','telegram-leads-activate-20261020.service'):
 q=subprocess.run(['systemctl','show',name,'-p','ActiveState','--no-pager'],capture_output=True,text=True,timeout=10)
 print('RETIRED_UNIT',name,q.stdout.strip())
 if 'ActiveState=active' in q.stdout:raise RuntimeError('Retired timer/service active')
q=subprocess.run(['df','-hT','/'],capture_output=True,text=True,timeout=11)
print('DISK='+q.stdout.strip().replace('\n',' | '))
print('REMAINING_EXTERNAL_REA_FINAL='+str(Path('/home/ubuntu/rea-final-runtime').is_dir()))
print('REMAINING_EXTERNAL_CODEX_AGENT='+str(Path('/home/ubuntu/codex-agent').is_dir()))
print('REMAINING_GLOBAL_PM2='+str(Path('/root/.pm2').is_dir()))
print('POST_MIGRATION_AUDIT=PASS')
